local command = (function()
return cmd(sleep,0
pulse; effectmagnitude,1,1,1;
value, (2 + 3) * 4 nextvalue, false or 7;
value, function() return {3, 4} end nextvalue, ({9, 10})[2];
value, "literal" nextvalue, [=[long literal]=];
value, math.max(2, 3) nextvalue, .5e+1;
value, (function(x) return x end){11} nextvalue, -2^3;
)
end)()
local actor={calls={}}
for _,name in ipairs({'sleep','pulse','effectmagnitude','value','nextvalue'}) do
 actor[name]=function(self,...) self.calls[#self.calls+1]={name,...} end
end
command(actor)
local calls=actor.calls
assert(#calls==13 and calls[1][2]==0 and #calls[2]==1)
assert(calls[4][2]==20 and calls[5][2]==7 and calls[7][2]==10)
assert(calls[11][2]==5 and calls[13][2]==-8)
assert(calls[6][2]()[2]==4 and calls[12][2][1]==11)
print('native regression matrix: 13 calls, expression values and callback/table arguments verified')
